INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,集合', 1, 'Java 的基本数据类型有哪些？int 和 Integer 有什么区别？', 'Java 有 8 种基本数据类型：byte、short、int、long、float、double、char、boolean。int 是基本类型，直接存值；Integer 是 int 的包装类，是对象，可以为 null，也可以用于集合、泛型等需要对象的场景。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,线程', 1, 'String、StringBuilder、StringBuffer 的区别？', 'String 是不可变对象，每次拼接都会产生新对象；StringBuilder 可变、效率高，但线程不安全；StringBuffer 也是可变的，方法加了同步，线程安全但性能略低。单线程拼接字符串优先用 StringBuilder。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础', 1, '== 和 equals() 的区别？', '== 比较的是变量保存的值。对基本类型来说比较具体数值；对引用类型来说比较对象地址。equals() 是对象方法，默认也比较地址，但 String、Integer 等类重写后通常比较内容。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,HashMap,Map', 1, 'HashMap 的底层结构是什么？为什么查询比较快？', 'HashMap 底层主要是数组 + 链表 + 红黑树。通过 key 的 hash 值定位数组下标，大多数情况下可以直接定位到很小的范围，所以查询效率接近 O(1)。当链表过长时会转成红黑树，降低极端冲突下的查询成本。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,List', 1, 'ArrayList 和 LinkedList 的区别？', 'ArrayList 底层是动态数组，按下标查询快，尾部追加效率高，但中间插入删除可能需要移动元素。LinkedList 底层是双向链表，插入删除节点更灵活，但按下标查询需要遍历，随机访问较慢。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,异常', 1, '什么是异常？Exception 和 RuntimeException 有什么区别？', '异常是程序运行过程中出现的不正常情况。Exception 是异常体系中的常见父类，其中受检异常需要显式捕获或抛出；RuntimeException 是运行时异常，编译器不强制处理，常见如空指针、数组越界、类型转换错误。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础', 1, 'final 关键字可以修饰什么？分别表示什么含义？', 'final 可以修饰变量、方法和类。修饰变量表示只能赋值一次；修饰方法表示方法不能被子类重写；修饰类表示类不能被继承，例如 String。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Java 基础', '校招', 'Java,基础,多态', 1, '面向对象三大特性是什么？', '三大特性是封装、继承、多态。封装是隐藏内部实现，只暴露必要接口；继承是子类复用父类属性和方法；多态是同一个父类引用在运行时可以指向不同子类对象，从而表现出不同的行为。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot', 1, 'Spring Boot 相比传统 Spring 有什么优势？', 'Spring Boot 简化了 Spring 项目的搭建和配置，提供自动配置、起步依赖和内嵌 Web 容器。它减少了大量 XML 或手动配置，让开发者更快地启动项目并专注业务代码。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot,IoC', 1, '什么是 IoC？什么是 DI？', 'IoC 是控制反转，指对象的创建和依赖管理交给 Spring 容器，而不是业务代码自己 new。DI 是依赖注入，是 IoC 的具体实现方式，Spring 会把一个对象依赖的 Bean 自动注入进去。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot,序列化', 1, '@Controller 和 @RestController 的区别？', '@Controller 通常用于返回页面视图，如果要返回 JSON，需要配合 @ResponseBody。@RestController 等价于 @Controller + @ResponseBody，常用于前后端分离接口，方法返回值会直接序列化为 JSON。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot', 1, '@Autowired 是怎么注入 Bean 的？', '@Autowired 默认按类型从 Spring 容器中查找 Bean 并注入。如果同类型 Bean 有多个，可以结合 @Qualifier 指定名称，或使用 @Primary 设置优先级。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot,Map', 1, 'Spring Boot 项目一般分哪些层？', '常见分层是 Controller、Service、Mapper/Dao、Entity/DTO/VO。Controller 负责接收请求和返回响应，Service 负责业务逻辑，Mapper/Dao 负责数据库操作，实体和 DTO/VO 用于数据承载和传输。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot,AOP,切面', 1, '什么是 AOP？你用 AOP 统计接口耗时怎么实现？', 'AOP 是面向切面编程，用来把日志、权限、耗时统计等横切逻辑从业务代码中抽离出来。统计接口耗时可以定义切面，拦截 Controller 或 Service 方法，在方法执行前记录开始时间，执行后计算耗时并打印日志。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot,异常', 1, '统一异常处理怎么做？', '可以使用 @ControllerAdvice 定义全局异常处理类，再用 @ExceptionHandler 捕获指定异常，统一返回错误码、错误信息和 Result 结构。这样可以避免每个接口重复 try-catch，也能保证前端拿到统一格式。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Spring Boot 和 Spring', '校招', 'Spring,Spring Boot', 1, 'RESTful API 是什么？常见 HTTP 方法有哪些？', 'RESTful API 是一种接口设计风格，通常用 URL 表示资源，用 HTTP 方法表示操作。常见方法有 GET 查询、POST 新增、PUT 修改、DELETE 删除，接口返回一般使用 JSON。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis', 1, 'MySQL 常见的数据类型有哪些？', '常见类型包括整数类型 int、bigint，小数类型 decimal、double，字符串类型 varchar、char、text，日期时间类型 date、datetime、timestamp。实际开发中要根据字段含义、长度和精度选择合适类型。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,索引', 1, '主键、外键、索引分别是什么？', '主键用于唯一标识一条记录，不能为空且不能重复。外键用于建立两张表之间的关联关系。索引是提高查询效率的数据结构，可以加快查询，但会增加写入和维护成本。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,索引', 1, '索引为什么能提高查询效率？', '索引类似目录，数据库可以通过索引快速定位到目标数据，而不是全表扫描。MySQL InnoDB 常用 B+ 树索引，适合范围查询和排序。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,索引', 1, '索引是不是越多越好？为什么？', '不是。索引会占用磁盘空间，并且插入、更新、删除数据时需要维护索引，过多索引会降低写入性能。应该给高频查询条件、排序字段、关联字段建立合适索引。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,分页', 1, 'where、group by、order by、limit 的作用？', 'where 用于过滤行数据，group by 用于按字段分组统计，order by 用于排序，limit 用于限制返回数量，分页查询常用 limit offset,size 的形式。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,分页', 1, '分页查询怎么写 SQL？', '基础写法是 select * from table order by id limit 起始位置, 每页条数。例如查询第 2 页、每页 10 条，起始位置是 10，可以写 limit 10,10。实际项目中也可以用 PageHelper 或 MyBatis-Plus 分页插件。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis', 1, 'MyBatis 中 #{} 和 ${} 的区别？', '#{} 使用预编译占位符，可以防止 SQL 注入，适合传普通参数；${} 是字符串拼接，可能有 SQL 注入风险，通常只在动态表名、排序字段等特殊场景谨慎使用。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,分页,Map', 1, 'MyBatis-Plus 相比 MyBatis 方便在哪里？', 'MyBatis-Plus 提供了通用 CRUD、条件构造器、分页插件等能力，可以减少简单 SQL 和 Mapper 方法的重复编写。但复杂业务 SQL 仍然可以自定义。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,事务', 1, '什么是事务？ACID 是什么？', '事务是数据库中一组操作的执行单元，要么全部成功，要么全部失败。ACID 指原子性、一致性、隔离性、持久性，用来保证数据操作的可靠性。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('MySQL 和 MyBatis', '校招', 'MySQL,MyBatis,事务', 1, '多表事务处理可能遇到什么问题？', '多表事务中如果中间某一步失败，需要整体回滚，否则会出现部分表更新成功、部分表失败的数据不一致问题。项目中通常在 Service 层使用 @Transactional 保证同一业务操作的原子性。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, 'JWT 是什么？由哪三部分组成？', 'JWT 是一种无状态登录认证方案，常用于前后端分离项目。它由 Header、Payload、Signature 三部分组成，Header 表示令牌类型和算法，Payload 保存用户信息或声明，Signature 用于防止篡改。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, 'JWT 登录流程一般是什么？', '用户提交账号密码，后端校验成功后生成 JWT 返回给前端。前端保存 Token，后续请求在请求头中携带 Token。后端拦截请求，校验 Token 合法性和有效期，通过后再放行。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证,RAG', 1, 'Token 一般放在哪里？前端请求时怎么携带？', 'Token 可以放在 localStorage、sessionStorage 或 Cookie 中。前后端分离项目常在请求头 Authorization 中携带，例如 Authorization: Bearer token。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, 'JWT 和 Session 登录有什么区别？', 'Session 登录需要服务端保存会话状态，适合传统单体应用；JWT 本身携带用户信息，服务端通常不保存登录状态，更适合分布式和前后端分离场景。但 JWT 一旦签发，在过期前主动失效相对麻烦。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, '自定义 Filter 校验 Token 主要做什么？', 'Filter 会在请求进入 Controller 前执行，主要负责从请求头中取出 Token，判断是否存在、是否过期、签名是否正确，并解析用户信息。如果校验失败就直接返回 401，成功则放行请求。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, '如果 Token 过期了，后端应该返回什么？', '一般返回 401 Unauthorized，并给出统一错误信息，例如 token expired。前端收到后可以跳转登录页，或者调用刷新 Token 接口。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, '什么是登录白名单？为什么需要？', '登录白名单是指不需要 Token 也能访问的接口，比如登录、注册、验证码、静态资源等。如果没有白名单，用户还没登录就无法访问登录接口，会形成逻辑冲突。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('JWT 和登录认证', '校招', 'JWT,认证', 1, 'RBAC 是什么？', 'RBAC 是基于角色的权限控制。一般是用户关联角色，角色关联权限，系统判断用户是否拥有某个权限时，会通过用户的角色去间接判断。这样比直接给每个用户配置权限更容易维护。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存,序列化', 1, 'Redis 是什么？为什么快？', 'Redis 是基于内存的高性能键值数据库。它快的原因主要是数据存储在内存中，采用高效的数据结构，并且核心命令执行模型简单，网络和序列化开销也较低。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存,集合,List', 1, 'Redis 常见数据类型有哪些？', '常见类型有 String、Hash、List、Set、ZSet。String 适合简单缓存，Hash 适合对象属性，List 适合队列或列表，Set 适合去重集合，ZSet 适合排行榜或带权重排序。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存', 1, 'Redis Hash 适合存什么数据？', 'Hash 适合存储对象结构，例如用户信息、设备状态、床位状态等。一个 key 对应一个对象，field 保存属性名，value 保存属性值，读取和更新单个字段比较方便。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存,事务,消息队列', 1, '缓存和数据库数据不一致怎么办？', '常见做法是更新数据库后删除缓存，下一次查询再重建缓存。对于一致性要求高的场景，可以使用事务、消息队列或延迟双删等方案，但也要结合业务接受程度。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存', 1, '什么是缓存穿透、击穿、雪崩？', '缓存穿透是查询不存在的数据，缓存和数据库都没有，导致请求打到数据库；击穿是热点 key 失效瞬间大量请求打到数据库；雪崩是大量 key 同时失效导致数据库压力暴增。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Redis 和缓存', '校招', 'Redis,缓存,MySQL', 1, '为什么设备状态写入 Redis Hash，而不是每次直接写 MySQL？', '设备状态变化频繁，直接每次写 MySQL 会增加数据库压力。Redis Hash 读写快，适合保存实时状态，再通过定时任务或批量策略落库，可以兼顾实时性和数据库稳定性。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端', 1, 'Vue 是什么？它解决了什么问题？', 'Vue 是前端渐进式框架，主要用于构建用户界面。它通过组件化、数据驱动视图、指令等方式简化页面开发，让开发者更关注数据和业务逻辑。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端', 1, 'Vue 的双向绑定是什么？', '双向绑定指数据变化会自动更新页面，页面输入变化也会反向更新数据。典型用法是 v-model，常用于表单输入框、选择框等场景。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端', 1, '前端如何调用后端接口？', '前端通常使用 Axios 或 fetch 发送 HTTP 请求，请求后端 RESTful API。请求时会携带参数、请求头和 Token，后端返回 JSON 后前端再渲染页面。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端,拦截器', 1, 'Axios 的作用是什么？', 'Axios 是前端常用的 HTTP 请求库，可以发送 GET、POST、PUT、DELETE 等请求，也支持请求拦截器、响应拦截器、统一设置 baseURL 和 Token。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端', 1, '前后端分离项目中怎么约定数据格式？', '通常约定统一响应结构，例如 code、message、data。code 表示业务状态，message 表示提示信息，data 存放真正的数据。这样前端可以统一处理成功、失败、未登录等情况。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端,异常', 1, '数据看板页面一般有哪些模块？', '能源数据看板通常包括概览指标、趋势图、工厂列表、实时运行状态、异常告警、时间筛选和详情面板。核心是让管理层快速看到关键数据和异常情况。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('Vue 和前端基础', '校招', 'Vue,前端', 1, '后端接口返回数据为空，前端应该怎么处理？', '前端应做空状态处理，比如显示暂无数据、默认值或空图表，而不是页面报错。同时可以检查接口参数、时间范围和后端返回 code，必要时给用户提示。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,JWT,异常,分页', 2, '智能学习后台管理系统中主要负责哪些接口？', '可以回答负责员工、部门等后台管理模块，包含新增、删除、修改、分页查询、多条件筛选等接口，同时做了统一 Result 响应、异常处理、JWT 登录校验和文件上传等基础能力。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历', 2, '统一 Result 响应为什么有必要？', '统一 Result 可以让前后端约定固定格式，例如 code、message、data。这样前端不用为每个接口单独判断返回结构，也方便统一处理错误、未登录和业务提示。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,MyBatis,分页', 2, 'PageHelper 分页的基本原理是什么？', 'PageHelper 会拦截 MyBatis 执行的 SQL，根据分页参数自动拼接 limit，并额外执行 count 查询获取总数。开发者只需要在查询前设置页码和页大小。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历', 2, '阿里云 OSS 文件上传流程是什么？', '一般流程是前端选择文件并提交，后端接收 MultipartFile，生成唯一文件名，调用 OSS SDK 上传到指定 Bucket，上传成功后返回文件访问 URL 或对象 key。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,Redis', 2, '养老物联网项目中设备数据怎么进入系统？', '设备数据先上报到物联网平台，例如华为云 IoTDA，再通过 AMQP 消息消费的方式进入后端系统。后端解析消息中的设备属性，如心率、离床状态等，写入 Redis 或数据库。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历', 2, 'AMQP 在项目中起什么作用？', 'AMQP 是消息通信协议，在项目中用于接收设备上报消息。它能把设备数据和业务处理解耦，后端通过消费消息异步处理数据，提升系统扩展性和稳定性。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历', 2, 'WebSocket 和 HTTP 有什么区别？为什么报警推送用 WebSocket？', 'HTTP 通常是客户端发起请求、服务端响应；WebSocket 建立连接后可以双向实时通信。报警消息需要服务端主动推送给后台页面，所以用 WebSocket 更适合。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,微服务,Nacos', 2, 'Nacos 是做什么的？', 'Nacos 常用于服务注册发现和配置管理。在微服务中，每个服务启动后注册到 Nacos，其他服务可以通过服务名发现实例地址，实现服务间调用。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,Nacos,OpenFeign', 2, 'OpenFeign 的作用是什么？', 'OpenFeign 是声明式 HTTP 客户端，可以像调用本地接口一样调用远程服务。它简化了服务间 HTTP 调用代码，通常和 Nacos、负载均衡一起使用。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('项目经历追问', '校招', '项目,经历,微服务,Gateway', 2, 'Gateway 为什么要做统一入口？', 'Gateway 作为微服务统一入口，可以集中处理路由转发、登录校验、跨域、限流、日志等公共逻辑，避免每个服务重复实现，也方便前端统一访问。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目', 2, '能源数据可视化平台主要解决什么业务问题？', '它主要解决能源公司和工厂数据分散、管理层查看不方便的问题。系统把多来源工厂运行数据接入后集中展示到看板，管理层可以在办公室远程查看关键指标和运行状态。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目,Spring,Spring Boot,Vue', 2, 'Vue1 负责哪些页面？Spring Boot 负责哪些接口？', 'Vue1 主要负责前端看板页面、数据列表、筛选条件和图表展示；Spring Boot 负责提供数据查询接口、字段映射后的数据返回、业务处理和对接后端数据源。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目', 2, '工厂数据接入时，字段映射是什么意思？', '不同工厂或能源公司的数据字段名称和格式可能不一致，字段映射就是把外部字段转换成系统内部统一字段，例如把不同来源的设备编号、能耗值、时间字段映射成统一模型。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目', 2, '不同能源公司的数据格式不一样，怎么处理？', '可以先定义统一的数据模型，再针对不同来源写适配逻辑，完成字段映射、类型转换、单位转换和缺失值处理。这样上层业务和前端只依赖统一格式，降低维护成本。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目,异常', 2, '管理端数据看板一般展示哪些指标？', '一般展示工厂运行状态、能耗总量、用电/用气/用水趋势、设备状态、异常告警、同比环比变化、工厂排名和最近更新时间等指标。具体展示取决于业务重点。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目', 2, '接口联调时遇到问题怎么排查？', '先用 Postman 或浏览器开发者工具确认请求地址、参数、请求头和 Token 是否正确；再看后端日志和接口返回码；如果是数据问题，再检查数据库、字段映射和第三方数据源。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目,索引,缓存,分页', 2, '页面数据加载慢从哪些方面优化？', '可以从前端和后端两边排查。前端减少重复请求、使用分页和懒加载；后端优化 SQL、加索引、使用缓存、减少无用字段返回；如果数据量大，可以做接口分页或聚合统计。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('实习经历追问', '校招', '实习,项目,异常', 2, '这个系统相比线下查看工厂数据有什么优势？', '优势是数据集中、实时性更好、查看成本更低。管理层不需要频繁到现场，就能通过看板了解工厂运行情况，还可以更快发现异常并做决策。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,MySQL,Redis,Spring,Spring Boot,MyBatis,JWT', 2, '请做一个 1 分钟自我介绍。', '可以这样说：您好，我叫倪瀚呈，是安徽工业大学人工智能专业本科生，求职方向是 Java 后端或全栈开发。我熟悉 Java、Spring Boot、MyBatis、MySQL、JWT 等技术，也了解 Redis、WebSocket、Spring Cloud、Nacos、Docker 等内容。项目方面，我做过后台管理系统、养老物联网系统和微服务商城实践，实习中参与过能源数据可视化平台开发，使用 Vue1 和 Spring Boot 完成数据看板和接口服务。希望能在实习岗位中继续提升工程能力，参与真实业务系统开发。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,Spring,Spring Boot,MyBatis', 2, '你为什么想做 Java 后端开发？', '我对后端开发比较感兴趣，因为后端涉及业务逻辑、数据库、接口设计、权限认证和系统稳定性，能接触到完整业务流程。Java 生态成熟，Spring Boot、MyBatis、Spring Cloud 等框架在企业系统中使用广泛，也比较适合我目前的项目经历。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,Redis,Spring,JWT', 2, '你最熟悉的项目是哪一个？', '可以选择养老智能物联网系统，因为它涉及后台管理、设备数据接入、Redis、WebSocket、Spring Security、JWT 等内容。回答时重点说清楚自己负责的模块、数据流转过程和遇到的问题。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,异常', 2, '项目中遇到最难的问题是什么？怎么解决？', '可以回答设备数据链路或登录鉴权联调。比如设备数据格式不统一时，先分析上报字段，再做统一模型和字段映射；接口异常时通过日志、Postman、数据库数据逐步定位，最后修正字段、参数或业务逻辑。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,Spring,Spring Boot,JWT,AOP,IoC,异常', 2, '你对 Spring Boot 的理解到什么程度？', '可以回答：我能使用 Spring Boot 搭建 RESTful API，理解 Controller、Service、Mapper 分层，掌握 IoC/DI、统一异常处理、JWT Filter、AOP 日志统计等常见用法。对于自动配置和底层源码还在继续学习。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO question_bank (category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at) VALUES ('开放题', '校招', '开放题,综合,索引,异常', 2, '如果重新优化一个项目，你会优化哪里？', '可以回答：我会优先优化接口规范、异常处理、日志记录和 SQL 性能。例如统一响应结构、完善参数校验、给高频查询字段加索引、补充接口文档和部署文档，让项目更接近企业开发规范。', '个人整理', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));